// Uma busca para cada combinação de cidade x tipo
const f = $input.first().json;
const cidades = String(f.Cidades || '').split('\n').map(s => s.trim()).filter(Boolean);
let tipos = f.Tipos;
if (!Array.isArray(tipos)) tipos = String(tipos || 'pousada').split(',').map(s => s.trim());
const out = [];
for (const c of cidades) for (const t of tipos) out.push({ json: { textQuery: `${t} em ${c}` } });
return out;

// Limpa, remove duplicados, descarta o que não é hospedagem e dá uma nota de prioridade
const cfg = $('Config').first().json;
const HOSPEDAGEM = /hotel|pousada|hospedaria|hospedagem|motel|hostel|albergue|chal[eé]|resort|pens[aã]o|camping|flat|apart|cama e caf|acomoda|lodging|inn\b|bed and breakfast|guest/i;
const seen = new Set();
const out = [];
const agora = new Date().toISOString();

for (const item of $input.all()) {
  const p = item.json;
  const id = p.place_id || p.business_id;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  if (p.is_permanently_closed) continue;
  if (!(p.types || []).some(t => HOSPEDAGEM.test(t))) continue;

  const nome = p.name || '';
  const endereco = (p.full_address || '').replace(nome + ' - ', '');
  const m = (p.city || '').match(/^(.*?)\s*-\s*([A-Z]{2})$/);
  const cidade = m ? m[1].trim() : (p.city || '');
  const uf = m ? m[2] : '';

  // Telefone vem como 081987591121 ou +55 81 98759-1121: normaliza para DDD + número
  let dig = String(p.phone_number || '').replace(/\D/g, '');
  if (dig.startsWith('55') && dig.length >= 12) dig = dig.slice(2);
  dig = dig.replace(/^0+/, '');
  const celular = dig.length === 11 && dig[2] === '9';
  const telefone = dig.length === 11 ? '(' + dig.slice(0,2) + ') ' + dig.slice(2,7) + '-' + dig.slice(7)
                 : dig.length === 10 ? '(' + dig.slice(0,2) + ') ' + dig.slice(2,6) + '-' + dig.slice(6)
                 : (p.phone_number || '');

  const site = p.website || '';
  const nota = p.rating ?? '';
  const avaliacoes = p.review_count ?? 0;
  const siteEhOta = /booking\.com|airbnb|expedia|decolar|trivago|hoteis\.com|instagram\.com|facebook\.com|wa\.me|linktr\.ee|bit\.ly/i.test(site);

  // Prioridade: quanto maior, mais provável que tenha as dores que você resolve
  let score = 0;
  const motivos = [];
  if (!site || siteEhOta) { score += 3; motivos.push(site ? 'site é OTA/rede social' : 'sem site'); }
  if (celular) { score += 2; motivos.push('celular (provável WhatsApp)'); }
  if (avaliacoes >= 20 && avaliacoes <= 400) { score += 2; motivos.push('porte pequeno/médio'); }
  if (avaliacoes > 1500) { score -= 2; motivos.push('muito grande (provável rede)'); }
  if (nota !== '' && nota < 4.3) { score += 1; motivos.push('nota abaixo de 4,3'); }
  if (!dig) { score -= 2; motivos.push('sem telefone'); }

  // O sandbox do n8n não tem URLSearchParams: monta a query na mão
  const query = Object.entries({ lead: id, hotel: nome, cidade: cidade && uf ? cidade + '/' + uf : cidade, origem: 'Captação n8n', contato: telefone })
    .map(([k, v]) => k + '=' + encodeURIComponent(v)).join('&');

  out.push({ json: {
    place_id: id,
    nome, cidade, uf, endereco, telefone,
    whatsapp: celular ? 'https://wa.me/55' + dig : '',
    site, nota, avaliacoes,
    maps: p.place_link || '',
    score, motivos: motivos.join('; '),
    link_entrevista: cfg.questionario_url + '?' + query,
    status: 'Novo',
    temperatura: '', proximo_passo: '', data_retorno: '',
    capturado_em: agora
  }});
}
return out;

// Mesma senha do nó 'Checar senha' do workflow do painel
const SENHA = 'TROQUE_ESTA_SENHA';

const body = $input.first().json.body || {};
if (SENHA === 'TROQUE_ESTA_SENHA') throw new Error('Defina a SENHA neste nó');
if (String(body.senha ?? '').trim() !== SENHA.trim()) throw new Error('Senha incorreta: recebi ' + (body.senha ? body.senha.length + ' caracteres' : 'nenhuma senha'));
// Deixa no mesmo formato que o formulário entrega
return [{ json: { Cidades: String(body.cidades || ''), Tipos: Array.isArray(body.tipos) ? body.tipos : [] } }];
